    [147] = {
        {
            id = 19356,
            score = 36,
            author = "1144",
            text = "Morgan the Collector is the mob you are looking for. He is located at the Brackwell Pumpkin Patch at 71,80. There are several mobs around him so the quest can be slightly difficult if soloing.",
            date = "2007-01-04T15:50:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=147#comments:id=19356",
        },
        {
            id = 74715,
            score = 29,
            author = "Flyv",
            text = "The prereq for this quest is The Collector, http://www.wowhead.com/?quest=123",
            date = "2007-04-29T02:35:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=147#comments:id=74715",
        },
        {
            id = 228427,
            score = 14,
            author = "22655",
            text = "It appears that the 3 named mobs at the house in Brackwell Pampkin Patch always spawn together, and would not respawn until all three is dead.\n\nSo if you go to the house and can't find Morgan the Collector, kill the rest first -- then Morgan will respawn (along with others).\n\nThis prabably isn't a bug ... devs presumably made it this way so that some players can clear the house solo by using \"hit-and-run\" tactics.\n\nBy the way, make sure to clear the area around the house before engaging the named mobs inside the house.  It seems that you can pull the Defias mobs without getting the named mobs involved (assuming that you don't fight on their footsteps).",
            date = "2008-02-02T17:11:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=147#comments:id=228427",
        },
        {
            id = 721619,
            score = 8,
            author = "Elamir",
            text = "You will need to have Gold Pickup Schedule (http://www.wowhead.com/?item=1307) to do this quest.\nInstead of that, its easy enough for one player to finish it.",
            date = "2009-05-20T00:02:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=147#comments:id=721619",
        },
        {
            id = 1817612,
            score = 7,
            author = "1094310",
            text = "These are the people inside the house with The Collector and himself. It shows their abilities, drops, pickpockets, coordinates, etc:\n\n[npc=473 domain=www]\n[npc=880 domain=www]\n[npc=881 domain=www]\n\nThe house is surrounded by a couple bandits.",
            date = "2013-02-24T08:09:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=147#comments:id=1817612",
        },
    },
    [176] = {
        {
            id = 219592,
            score = 94,
            author = "53109",
            text = "Marshal Dughan wants you, and not him to kill Hogger for a reason.\nHe wouldn't last 10 seconds against Hogger, and you should not attempt this without a 40 man raid.\n\nNerf Hogger, blizzard!",
            date = "2008-01-17T09:57:38-06:00",
