    [196] = {
        {
            id = 52521,
            score = 9,
            author = "27922",
            text = "32, 37\n\nNear the coast.",
            date = "2007-03-17T06:39:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=196#comments:id=52521",
        },
        {
            id = 214812,
            score = 2,
            author = "ttsaypra",
            text = "So easy quest! there are millions of raptors about 31,40 Did this on 5 min as lv 39",
            date = "2008-01-08T09:25:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=196#comments:id=214812",
        },
        {
            id = 260421,
            score = 1,
            author = "102269",
            text = "just a note, if you're a female instead of \"old chap\" he'll say \"fair lady.\"\n\nThese raptors are literally everywhere by the Gurabashi Arena. You cannot miss them. The only thing I would say is to bring bandages and/or food, because otherwise there is a lot of down time. The respawn on the raptors isn't terrible, so you won't get killed by respawns before you're ready, and there will always be enough for you to complete the quest.",
            date = "2008-03-26T16:45:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=196#comments:id=260421",
        },
        {
            id = 273015,
            score = 1,
            author = "143324",
            text = "I soloed this as 37 rogue easy. 31,40 confirmed, alot of raptors",
            date = "2008-04-17T00:24:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=196#comments:id=273015",
        },
        {
            id = 3223688,
            score = 1,
            author = "Ringthane",
            text = "Tigers? Go kill 10, then 10 more, then 5, then the big tiger.\n\nPanthers? Let's kill 10, then another 10, then 5, then the king panther.\n\nRaptors?  Again, we'll start with 10.  Then go kill... let's say 10.  Then take care of another...\n\n10?\n\nWas Blizzard drunk when they designed Cata quests?  Half of them are horrible, and the rest just don't make sense.",
            date = "2020-08-16T14:42:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=196#comments:id=3223688",
        },
    },
    [197] = {
        {
            id = 72334,
            score = 11,
            author = "19022",
            text = "Tethis has 5262 healthpoints and has a special attack called \"Tendon Rip\" much like the crocs outside Grom'Gol. (Slows down movementspeed).\nHe hits plate for 85-110.\nHe can be both slowed and feared, so kiting is possible.\n\nMy kill location was 28.44",
            date = "2007-04-24T20:26:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=197#comments:id=72334",
        },
        {
            id = 217397,
            score = 11,
            author = "Yeoman",
            text = "Followup of this quest chain is Big Game Hunter (http://www.wowhead.com/?quest=208), but available only after completing all 3 separate quest chains:\n\nTiger Mastery (http://www.wowhead.com/?quest=188) Raptor Mastery (http://www.wowhead.com/?quest=197) (this quest)\nPanther Mastery (http://www.wowhead.com/?quest=190)",
            date = "2008-01-12T19:29:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=197#comments:id=217397",
        },
        {
            id = 1672039,
            score = 10,
            author = "993071",
            text = "I Cata found him at 59,58.\n\nAlso possible:\n59, 62\n58, 59\n60, 62\n\nHis blue - other raptors are purple, so you can easy find him.",
            date = "2012-05-31T14:44:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=197#comments:id=1672039",
        },
        {
            id = 553396,
            score = 8,
            author = "142629",
            text = "Found him at 28,42. He's blue! So don't brother scrolling over the red raptors hoping for a hit. Level 43, non elite. I killed him at 80 so I cant comment on the fight but, yah, hope what I did post is helpful.\n\nFor those without coords: He pats along the western side of the Arena. If you look on your main map, you should find him in the area constituting the \"GURU\" and \"AR\" in Gurubashi Arena. Look around that area. I find mine on top of the hill leading down to the beach.",
            date = "2009-01-08T17:16:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=197#comments:id=553396",
        },
        {
            id = 53872,
            score = 7,
            author = "31458",
            text = "This can be acquired by a level 29 twink if you have some help with the quest.  Just make to start the chain early enough so that you have enough XP to finish it all!",
            date = "2007-03-19T17:38:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=197#comments:id=53872",
        },
    },
    [208] = {
        {
            id = 2194,
            score = 52,
            author = "lollersk8r",
            text = "If you can get a higher level to run you through the questlines Panther Mastery (http://www.wowhead.com/?quest=190), Tiger Mastery (http://www.wowhead.com/?quest=185), Raptor Mastery (http://www.wowhead.com/?quest=194), and Big Game Hunter (http://www.wowhead.com/?quest=208) you will get a very solid set of gear for a 29 twink hunter or for any other leather class.",
            date = "2006-10-23T18:39:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=208#comments:id=2194",
        },
        {
            id = 70631,
            score = 21,
            author = "15573",
            text = "If you fail at killing this cat on your first attempt, but get him below 50%, the two ads will remain with him even when he resets. Two additional cats will then spawn when his health crawls below 50% again.\n\nThis means that if you're going alone, you basically only have one shot at taking him down.",
            date = "2007-04-21T18:53:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=208#comments:id=70631",
