    [744] = {
        {
            id = 66972,
            score = 7,
            author = "43096",
            text = "Thought i'd add one too cause only Crazytroll added one..So when you take the quest from the Tauren you take the right elivator down and go east of it keep going straight and you'll find the harpies kill 10 of each color there are white and blue the white ones give you azure the blue give you bronze, you'll get them all after you kill 10-15 of em well thats what i did when i was lvl 9 well Good Luck and happy Killing =P",
            date = "2007-04-14T03:47:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=744#comments:id=66972",
        },
        {
            id = 127980,
            score = 5,
            author = "42007",
            text = "I tried the above coords & nothing was there.  The harpies were at 56, 17, NW of Red Rocks.",
            date = "2007-07-27T21:07:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=744#comments:id=127980",
        },
        {
            id = 237019,
            score = 5,
            author = "hawke",
            text = "Watch out for the Matriach, as they heal themself, so it make it hard for class with no healing ability (like warrior).\n\nTips for warrior:\nI would suggest you Harmstring them at around 40% HP, because they try to run away at  10%, and the last thing you want is to get a caster pull :/ ! You can always try to War Stomp when they heal too, make it easier for you.\n\nAnd btw, have some patience, the drop rate is HORRIBLE. Matriarch drop the Bronze Feather, and Sorceress drop the Azure Feathers...",
            date = "2008-02-16T00:17:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=744#comments:id=237019",
        },
        {
            id = 242556,
            score = 5,
            author = "113818",
            text = "Location 32, 27\nDrop rate is 60%~\n\nSorceress has 176 HP~ and uses Frost attacks\nMatriarchs has 207 HP~ uses Lightning attacks and Heals",
            date = "2008-02-24T11:22:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=744#comments:id=242556",
        },
        {
            id = 264828,
            score = 5,
            author = "DistinctlyBenign",
            text = "I would like to point out that if one has finished all of the other mulgore quests this is a great quest to finish off the area with if you want to get as much XP as possible before the barrens. This is because you are essentaly grinding the harpies which give around 90 XP each at the level, of which you'll be killing lots, and then you get an additional 850 XP after you finish.",
            date = "2008-04-01T22:33:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=744#comments:id=264828",
        },
    },
    [746] = {
        {
            id = 41152,
            score = 58,
            author = "Aryah",
            text = "You get the tools from the dwarves and break them at that same camp at 32, 48. The anvil is at the back left corner of the camp.",
            date = "2007-02-23T15:03:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=746#comments:id=41152",
        },
        {
            id = 70688,
            score = 41,
            author = "41367",
            text = "If you are having trouble getting to the forge at the dwarven camp, you can always go to Thunder Bluff and use the forge by the blacksmith to create the broken tools.",
            date = "2007-04-21T21:05:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=746#comments:id=70688",
        },
        {
            id = 65666,
            score = 14,
            author = "4668",
            text = "Each [Prospector's Pick] produces one piece of [Broken Tools]",
            date = "2007-04-11T17:58:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=746#comments:id=65666",
        },
        {
            id = 428849,
