    [891] = {
        {
            id = 149155,
            score = 38,
            author = "69592",
            text = "The names of the Cannoneers is a reference to Smith & Wesson, the largest handgun manufacterer in the United States.",
            date = "2007-09-04T20:17:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=891#comments:id=149155",
        },
        {
            id = 1075349,
            score = 26,
            author = "447186",
            text = "Big change with Cataclysm. All of the alliance NPC's have moved out of the keep and down to 'The Merchant Coast', displacing the pirates. Only two officers need to be killed now along with the collection of the medals. The two officers, Lt. Buckland and Lt. Pyre, are located along 'The Merchant Coast' at 70,84. This is very close to the stockade holding Baron Longshore at 69.85. Lt. Buckland is down near the shore and Lt. Pyre is up near the archery butts. All of the Alliance NPC's along the way and around them drop the medals.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T13:33:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=891#comments:id=1075349",
        },
        {
            id = 14903,
            score = 19,
            author = "TheOnyx",
            text = "The medals have either a really high drop rate or a 100% drop rate when you have the appropriate quest. Everytime I've done the quest, I've had at least two other people with me, and by the time we had killed the three leaders for this quest, we'd already gotten all of the medals we needed.\n\nAlso note that in the first tower you encoutner after entering Northwatch, there will be a Blood Elf (http://www.wowhead.com/?npc=3465) that wants you to escort him back to Ratchet. It is suggested that you wait to do the escort until after you have killed all three leaders. If you enter the tower and do not see the Blood Elf, someone else is currently doing the quest (http://www.wowhead.com/?quest=898), so you'll have to wait.",
            date = "2006-12-13T14:38:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=891#comments:id=14903",
        },
        {
            id = 253630,
            score = 13,
            author = "73770",
            text = "Name of this quest is probably based upon the old movie \"The guns of Navarone\"",
            date = "2008-03-15T04:50:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=891#comments:id=253630",
        },
        {
            id = 1180735,
            score = 13,
            author = "Jollsy",
            text = "As of 4.0.3a you find the guards to kill just south of Ratchet where the pirates where before. Pyre is found near the sharpshooters (Just straigth forward when you enter around 70,84) . And Buckland is found walking from the boat on the road towards the little camp with the dog and baron Longshore.",
            date = "2010-11-24T08:40:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=891#comments:id=1180735",
        },
    },
    [895] = {
        {
            id = 1102990,
            score = 23,
            author = "ArashikageClan",
            text = "Also gives 125 rep with Booty Bay, Everlook, and Gadgetzan. No Bloodsail rep decrease.",
