        {
            id = 3734,
            score = 62,
            author = "5930",
            text = "Bucket of Bolts: 26, 79 ; outside the troll cave which is south of Anvilmar. http://www.wowhead.com/?object=178085\n\nChest: 22, 79 ; just west of where you found the bucket of bolts, near the campfire. http://www.wowhead.com/?object=178084\n\nBox: 20, 76 ; northwest from where you found the chest. http://www.wowhead.com/?object=148499",
            date = "2006-11-16T06:42:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=3361#comments:id=3734",
        },
        {
            id = 246918,
            score = 8,
            author = "JayRay",
            text = "Map: http://www.wowhead.com/?maps=1:262790224792204763",
