    [6342] = {
        {
            id = 387711,
            score = 14,
            author = "Malvado",
            text = "This is part 3 of the Night Elf flight quests. Other races are not eligible.",
            date = "2008-09-25T12:46:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6342#comments:id=387711",
        },
        {
            id = 281052,
            score = 8,
            author = "GoGoGodzilla",
            text = "This quest series is included in the game specifically to introduce young Night Elves (or whomever may be leveling in that area) to the town of Auberdine, where said elves may continue their questing and leveling.  This is an exceptionally easy quest chain, simply requiring a number of \"talk to this NPC\" completions.\n\nRemember to turn the quest in before you fly!\n\nAlso, the hippogryph is faster than the boat, but the boat can be fun.  Incidentally, this is the only traveling boat in the game (i.e., takes you from one location to another) which doesn't initiate a loading screen, but also always docks on the same side of the boat.  In other words, you board on the port side and the boat docks on the port side, as opposed to any of the other boats which alternate docking between port and starboard.\n\nIf you're standing anywhere on the boat, facing the front (bow), the port is the left side of the boat and the starboard is the right side.",
            date = "2008-05-02T10:39:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6342#comments:id=281052",
        },
        {
            id = 1469172,
            score = 3,
            author = "Wyr3d",
            text = "Once again, listed in Wowhead as doable by Worgen, but not ==",
            date = "2011-07-13T19:10:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6342#comments:id=1469172",
        },
    },
