    [6826] = {
        {
            id = 11136,
            score = 15,
            author = "Serpent",
            text = "Many people ask in game where Jeztor is.  The easiest way to find him is to open your map in AV and at the top/right of the map you will see two huts.  Jeztor is laying down in the south hut there.  You must interact with him to send him back to the Horde base.\n\nIf Jeztor arrives safely back at base you can turn in Stormpike Lieutenant's Flesh to get him up in the air.  If you do not take a beacon and simply send him he will attack Stormpike Graveyard and the bridge which is always good for the Horde.",
            date = "2006-12-08T13:35:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6826#comments:id=11136",
        },
        {
            id = 201687,
            score = 7,
            author = "WARBOSZ",
            text = "Jeztor is a female btw - undead. Runs to 49.85 in the horde camp to the south. If the alliance has control of some southern bases she'll fight them so an escort is a wise idea if you want her to make it to Frostwolf Keep.",
            date = "2007-12-15T10:28:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6826#comments:id=201687",
        },
