    [13624] = {
        {
            id = 1888410,
            score = 12,
            author = "Rocknight",
            text = "If you die due to lag, being bad, DCing, getting a phone-call, dog eating your mouse, whatever... speak to Sentinel Onaeya (near the ramp to the main building) and he will give you a new squad.",
            date = "2013-08-19T17:53:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13624#comments:id=1888410",
        },
        {
            id = 1212799,
            score = 8,
            author = "165655",
            text = "Fairly straightforward quest, you need to walk around on the battlefield with the three sentinels you are given and take out 10 of the Horde invaders and three of the big machines.  Make sure you don't draw aggro from more than two or three invaders at the same time, and try to take out nearby invaders before you go for the wreckers.  You should easily kill more than 10 invaders taking out three of the machines.",
            date = "2010-12-07T18:08:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13624#comments:id=1212799",
        },
        {
            id = 1296895,
            score = 8,
            author = "QuickBASIC",
            text = "Your squad despawns if you try to kill anything other than the mobs invading... so much for having a squad of Nightelves help me with my other quests.",
            date = "2011-01-16T20:18:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13624#comments:id=1296895",
        },
        {
            id = 1227030,
            score = 5,
            author = "168126",
            text = "These mobs don't grant experience when killed, so you will not be able to use victory rush or similar effects.",
            date = "2010-12-12T08:30:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13624#comments:id=1227030",
        },
    },
    [13626] = {
        {
            id = 1184282,
            score = 21,
            author = "Puli",
            text = "1. Equip the cloak and use it.\n\n2. Feero's Holy Hammer is at 26.3, 38.4 right in front of those 3 Ashenvale Wreckers, there is also 3 stones in ground next to the corpse.\n\n3. The Purifier's Prayer Book is top of the tower at 27.0,40.8. In the tower at top there is a lvl22 warlock and hes imp that can see you, so be rdy to kill them.",
            date = "2010-11-25T09:00:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13626#comments:id=1184282",
        },
        {
            id = 1205135,
            score = 18,
            author = "715246",
            text = "Remember to right click on the cape once you've equipped it. Otherwise it won't work.",
            date = "2010-12-03T23:15:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13626#comments:id=1205135",
        },
        {
