    [13798] = {
        {
            id = 1560013,
            score = 127,
            author = "Nasha",
            text = "While this quest is easy, it's unnecessarily long due to the 15 second cooldown on the item you must use, Accursed Ore. I will never understand why Blizzard likes to put long cooldowns on quest items in situations like this. *Click* *twiddle thumbs* *check facebook* *click* *go to wowhead and complain* *click*...\n\nIn unrelated information, it's fantastically fun to fly at 310% speed while appearing as an imp (Druid doing Loremaster). His legs and arms are a blur as he swiftly swims through the air.",
            date = "2011-11-01T20:30:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13798#comments:id=1560013",
        },
        {
            id = 2871797,
            score = 45,
            author = "JasperKazai",
            text = "Unnecessarily long cooldown on the item, oddly limiting range for the targeting circle, limited to two places to fire it off from, long pause between using the item and the meteor falling, mobs that run around so much they will probably run out of the meteor effect range before it goes off because of the long pause... This isn't a quest with the greatest design.",
            date = "2019-02-16T23:53:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13798#comments:id=2871797",
        },
        {
            id = 3173196,
            score = 42,
            author = "Headshot314",
            text = "This quest item has a 15 sec cooldown for no apparent reason,",
            date = "2019-11-23T13:55:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13798#comments:id=3173196",
        },
        {
            id = 1182839,
