    [13805] = {
        {
            id = 1076471,
            score = 102,
            author = "447186",
            text = "Enter the Dor'Danil Barrow Den and you will see red glowing dots on the floor. These lead the way to the Forest Heart, which is a big brown spiky egg shaped thing suspended in mid air. It's in the middle of one of the platforms with pathways off it. See the screenshot.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
