        {
            id = 1440137,
            score = 8,
            author = "Bergelmir",
            text = "The Lava Ragers are 22-23 elites, and the Freezing Surger you get does very little damage, so this is a somewhat hard quest. Stock up on bandages and potions if you're not (accompanied by) a healer.",
            date = "2011-06-12T17:05:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13884#comments:id=1440137",
