    [13947] = {
        {
            id = 1076928,
            score = 195,
            author = "447186",
            text = "Go see Thraka the Windrider Master inside the camp at 38,42. Tell her that you have been ordered to bomb Astranaar and she will give you a windrider to attack with. You will see the familiar vehicle controls come up and key 1 is for your bombs. Key 3 turns your mount around and heads back to camp. You will fly back and forth across Astranaar until you have managed to destroy enough vehicles and people. Easy quest and back to Captain Goggath to hand it in.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T18:49:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13947#comments:id=1076928",
        },
        {
            id = 2867509,
            score = 57,
