            date = "2016-02-07T17:15:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26464#comments:id=2305093",
        },
    },
    [26465] = {
        {
            id = 2584312,
            score = 9,
            author = "taurolyon",
            text = "With the 8.0.1 pre-expansion event, this quest area is phased and unable to be completed. This may change after the event.",
            date = "2018-07-24T21:07:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26465#comments:id=2584312",
        },
        {
            id = 2587365,
            score = 8,
            author = "neurocase",
            text = "Currently on 8.0, this and https://www.wowhead.com/quest=13602 are difficult (if not near impossible) to complete, thanks to The Zoram Strand phasing oddly due to its proximity with southern Darkshore. Speaking with https://www.wowhead.com/npc=141489 doesn't currently fix this either, at the moment (2/8/18) as she doesn't appear to be phasing the zone correctly, which is having this ripple effect on the Zoram Strand. I was only able to find 1/10 statuettes within the Ashenvale zone, but the rest are too deep within the Zoram Strand, and it didn't seem to respawn either. Hopefully, this phasing issue (and Zidormi, by extension) will be fixed when the expansion launches fully on the 14th.",
            date = "2018-08-02T23:45:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26465#comments:id=2587365",
        },
        {
            id = 2004726,
            score = 3,
            author = "BReal85",
            text = "Leads to Ruuzel (http://www.wowhead.com/quest=26466)",
            date = "2014-09-21T07:40:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26465#comments:id=2004726",
        },
        {
            id = 2552080,
            score = 3,
            author = "Habu64",
            text = "With the 7.3.5 scaling and changes, the Strand quests are not required for the achievement Ashenvale Quests (http://www.wowhead.com/achievement=4925/ashenvale-quests).  They are now flavor quests that lead to Blackfathom Deeps (http://www.wowhead.com/blackfathom-deeps) dungeon.",
            date = "2018-02-11T11:43:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26465#comments:id=2552080",
        },
        {
            id = 5975205,
            score = 2,
            author = "Suntarr",
            text = "This IS completable, it was phased out for me at first but then I realized I had a quest titled \"Hope\" available in the area. It appears to be part of a BfA quest chain. After finishing the chain and obtaining the achievement In Teldrassil's Shadow (https://www.wowhead.com/achievement=13251/in-teldrassils-shadow), you're able to return to the area and complete this quest as normal.",
            date = "2024-10-04T00:11:51-05:00",
