    [54781] = {
        {
            id = 6333766,
            score = 3,
            author = "eldiin",
            text = "The Domanaar Snack Packs are found in little crates around Stormarion Citadel. The containers do not show up as yellow dots on the map, making it harder to find them.  The only clue you get is that the containers are sparkly.  I've only done this quest once, so do not know if the crates are static each time you do this quest, or they're random, but I've compiled a list of coordinates of where I found my 6, because it was kind of hard at first to find them and figure maybe it will save someone a little bit of time.  And as a friendly reminder, if you're in a raid, the containers can be interacted with but you'll get a \"there is no loot\" message. That should give you the indication you need to drop raid to do this quest.\n\n/way #2405 27.01, 66.14\n/way #2405 25.26, 66.05\n/way #2405 25.27, 69.7\n/way #2405 27.43, 69.75\n/way #2405 25.97, 68.63 (inside building)\n/way #2405 25.98, 67.17 (inside building)",
            date = "2026-04-18T21:22:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=54781#comments:id=6333766",
        },
    },
    [64863] = {
        {
            id = 5787999,
            score = 3,
            author = "auryunderground",
            text = "The NPC dialogue for this quest:\n\nhttps://www.wowhead.com/npc=181056 says: Gear up, . Then we rendezvous with the Earth-Warder (https://warcraft.wiki.gg/wiki/Deathwing).\n\nhttps://www.wowhead.com/npc=181596 says: Neltharion can explain what has happened. I am certain of it.\n\nAs the player heads out into the hall, a blue dragon can be heard giving orders:\n\nLapisagos (https://warcraft.wiki.gg/wiki/Lapisagos) says: If they will not sleep, then they must be destroyed!",
            date = "2024-02-17T13:15:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=64863#comments:id=5787999",
        },
    },
